// WATCH_TARGETS: "name|url,name|url"
const raw = $env.WATCH_TARGETS || '';
return raw
  .split(',')
  .map((entry) => entry.trim())
  .filter(Boolean)
  .map((entry) => {
    const [name, url] = entry.includes('|') ? entry.split('|') : [entry, entry];
    const host = url.trim().replace(/^[a-z]+:\/\//i, '').split(/[/:?#]/)[0];
    return { json: { name: name.trim(), url: url.trim(), host } };
  });

// Compare this run with the previous one (kept in workflow static data)
// and emit a single item only when something changed.
const targets = $('Targets').all().map((item) => item.json);
const checks = $('Check').all().map((item) => item.json);
const dns = $('Resolve DNS').all().map((item) => item.json);
const publicIp = ($('Public IP').first().json || {}).ip;
const state = $getWorkflowStaticData('global');
state.targets = state.targets || {};

const alerts = [];
const now = new Date().toISOString();

targets.forEach((target, i) => {
  const check = checks[i] || {};
  const status = typeof check.statusCode === 'number' ? check.statusCode : null;
  const up = status !== null && status >= 200 && status < 400;
  const detail = status !== null ? `HTTP ${status}` : (check.error && check.error.message) || 'no response';
  const ips = ((dns[i] && dns[i].Answer) || [])
    .filter((answer) => answer.type === 1)
    .map((answer) => answer.data)
    .sort();

  const prev = state.targets[target.name];
  const base = { target: target.name, url: target.url };
  if (!prev) {
    if (!up) alerts.push({ ...base, event: 'DOWN', detail });
  } else {
    if (prev.up && !up) alerts.push({ ...base, event: 'DOWN', detail });
    if (!prev.up && up) alerts.push({ ...base, event: 'RECOVERED', detail });
    if (ips.length && prev.ips.length && ips.join(',') !== prev.ips.join(',')) {
      alerts.push({ ...base, event: 'IP_CHANGED', detail: `${prev.ips.join(', ')} -> ${ips.join(', ')}` });
    }
  }
  const changed = !prev || prev.up !== up;
  state.targets[target.name] = {
    up,
    url: target.url,
    detail,
    ips: ips.length ? ips : (prev ? prev.ips : []),
    checkedAt: now,
    since: changed ? now : prev.since,
  };
});


// Egress IP of the machine running n8n. Office allowlists break when this changes.
if ($env.WATCH_PUBLIC_IP === 'true' && publicIp) {
  const prevIp = state.publicIp && state.publicIp.ip;
  if (prevIp && prevIp !== publicIp) {
    alerts.push({ target: 'public-ip', url: '-', event: 'PUBLIC_IP_CHANGED', detail: `${prevIp} -> ${publicIp}` });
  }
  state.publicIp = { ip: publicIp, checkedAt: now, since: prevIp === publicIp ? state.publicIp.since : now };
}

// Keep the latest 50 alerts for the status page.
state.history = alerts.map((a) => ({ ...a, at: now })).concat(state.history || []).slice(0, 50);

if (!alerts.length) return [];
const text = alerts.map((a) => `[${a.event}] ${a.target} (${a.url}): ${a.detail}`).join('\n');
return [{ json: { alerts, text, checkedAt: now } }];

// Use Claude's summary when the call succeeded, otherwise send the raw alerts.
const incident = $('Detect changes').first().json;
const ai = $input.first().json;
const summary = ai && ai.content && ai.content[0] && ai.content[0].text;
const message = [`Server Watch alert (${incident.checkedAt})`, incident.text, summary ? `\nSummary:\n${summary}` : '']
  .filter(Boolean)
  .join('\n');
const first = incident.alerts[0];
const more = incident.alerts.length > 1 ? ` (+${incident.alerts.length - 1} more)` : '';
const subject = `Server Watch: ${first.event} ${first.target}${more}`;
return [{ json: { message, subject } }];

// Status page: renders the state kept by "Detect changes".
const token = $env.STATUS_TOKEN;
if (token && $json.query.token !== token) {
  return { json: { status: 401, html: 'Unauthorized' } };
}

const state = $getWorkflowStaticData('global');
const targets = Object.entries(state.targets || {});
const history = state.history || [];
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
const time = (iso) => (iso ? new Date(iso).toLocaleString('id-ID', { timeZone: 'Asia/Jakarta' }) : '-');
const down = targets.filter(([, t]) => !t.up).length;
const egress = state.publicIp
  ? `<div class="muted">Public IP of this monitor: <b>${esc(state.publicIp.ip)}</b> since ${time(state.publicIp.since)}</div>`
  : '';

const rows = targets.length
  ? targets.map(([name, t]) => `<tr>
      <td><span class="dot ${t.up ? 'up' : 'down'}"></span>${t.up ? 'Up' : 'Down'}</td>
      <td><b>${esc(name)}</b><div class="muted">${esc(t.url)}</div></td>
      <td>${esc(t.detail)}</td>
      <td>${esc((t.ips || []).join(', ') || '-')}</td>
      <td>${time(t.since)}</td>
      <td>${time(t.checkedAt)}</td></tr>`).join('')
  : '<tr><td colspan="6" class="muted">No checks yet. Activate the workflow and wait for the first run.</td></tr>';

const events = history.length
  ? history.map((a) => `<tr><td>${time(a.at)}</td><td><span class="tag ${a.event}">${a.event}</span></td><td>${esc(a.target)}</td><td>${esc(a.detail)}</td></tr>`).join('')
  : '<tr><td colspan="4" class="muted">No alerts yet.</td></tr>';

const html = `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="60">
<title>Server Watch</title><style>
body{font-family:system-ui,sans-serif;margin:0;background:#f5f6f8;color:#1b1f24}
main{max-width:980px;margin:0 auto;padding:24px 16px}
h1{font-size:22px;margin:0 0 4px}h2{font-size:15px;margin:28px 0 8px}
.summary{padding:12px 16px;border-radius:8px;margin:16px 0;font-weight:600}
.ok{background:#e6f4ea;color:#1e6b34}.bad{background:#fce8e6;color:#a1251b}
table{width:100%;border-collapse:collapse;background:#fff;border-radius:8px;overflow:hidden;font-size:14px}
th,td{text-align:left;padding:10px 12px;border-bottom:1px solid #eceef1;vertical-align:top}
th{background:#fafbfc;font-weight:600;color:#555}.muted{color:#777;font-size:12px}
.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:6px}
.dot.up{background:#2e9e4f}.dot.down{background:#d93025}
.tag{font-size:12px;font-weight:600;padding:2px 6px;border-radius:4px}
.DOWN{background:#fce8e6;color:#a1251b}.RECOVERED{background:#e6f4ea;color:#1e6b34}.IP_CHANGED,.PUBLIC_IP_CHANGED{background:#fef7e0;color:#8a5a00}
.wrap{overflow-x:auto}</style></head><body><main>
<h1>Server Watch</h1><div class="muted">Refreshes every minute</div>${egress}
<div class="summary ${down ? 'bad' : 'ok'}">${targets.length ? (down ? `${down} of ${targets.length} targets down` : `All ${targets.length} targets up`) : 'Waiting for the first check'}</div>
<div class="wrap"><table><tr><th>Status</th><th>Target</th><th>Last result</th><th>IP</th><th>Since</th><th>Checked</th></tr>${rows}</table></div>
<h2>Recent alerts</h2>
<div class="wrap"><table><tr><th>Time</th><th>Event</th><th>Target</th><th>Detail</th></tr>${events}</table></div>
</main></body></html>`;

return { json: { status: 200, html } };
